(() => {
  const html = (tag) => document.createElement(tag);
  const svg = (tag) => document.createElementNS("http://www.w3.org/2000/svg", tag);
  const camel = (p) => p.replace(/-([a-z])/g, (m, c) => c.toUpperCase());
  const one = (make, prop, value) => {
    const el = make();
    el.style[camel(prop)] = value;
    return [el.style.getPropertyValue(prop), el.hasAttribute("style") ? el.getAttribute("style") : null];
  };
  return [["display", "svg", "svg", ["none","initial","block","","garbage"].map((v) => [v, ...one(() => svg("svg"), "display", v)])], ["transform", "svg", "svg", ["translate(-50%,-50%) scale(1, 1)","translate(-50%,-50%) scale(0.5, 0.5)","translate(-50%,-50%) scale(0.25, 0.25)"].map((v) => [v, ...one(() => svg("svg"), "transform", v)])]];
})()
